import test from 'node:test';import assert from 'node:assert/strict';
import { awardLeaderBundle,inviteMemberBundle,buildLeaderBundleEmail,buildMemberBundleInvitation } from '../lib/disciple-bundles.js';
const store=()=>({disciples:[{id:'leader',name:'Leader',email:'l@example.com',status:'active',isKingdomLeader:true},{id:'member',name:'Member',email:'m@example.com',status:'active'}],orders:[],discipleBundleActions:[],auditLogs:[]});const deps={id:p=>`${p}_1`,now:()=> '2026-09-21T20:00:00.000Z'};
test('awards one complimentary zero-dollar Leader bundle idempotently',()=>{const s=store(),input={discipleId:'leader',campaignId:'launch',eventId:'event1',productIds:['vip','merch'],reason:'Leader welcome',actorId:'owner'};const first=awardLeaderBundle(s,input,deps),again=awardLeaderBundle(s,input,deps);assert.equal(first,again);assert.equal(s.orders.length,1);assert.equal(s.orders[0].orderType,'disciple_leader_bundle');assert.equal(s.orders[0].amountTotal,0);assert.equal(s.orders[0].commissionEligible,false);});
test('invites only an approved non-Leader with required optional disclosure',()=>{const s=store(),action=inviteMemberBundle(s,{discipleId:'member',campaignId:'launch',checkoutUrl:'https://kvnlive.com/bundle',expiresAt:'2026-10-01',actorId:'owner'},deps);assert.equal(action.mode,'paid_optional');assert.match(buildMemberBundleInvitation({disciple:s.disciples[1],checkoutUrl:action.checkoutUrl}).text,/Optional purchase—no purchase is required/i);assert.match(buildLeaderBundleEmail({disciple:s.disciples[0]}).text,/complimentary/i);assert.throws(()=>inviteMemberBundle(s,{discipleId:'leader',campaignId:'x',checkoutUrl:'https://x.test',actorId:'owner'},deps),/non-Leader/i);});
